def choose_move(observation):
    width = observation['grid_width']
    height = observation['grid_height']
    px, py = observation['self_position']
    resources = observation['resources']
    obstacles = set(tuple(o) for o in observation['obstacles'])
    opponent_pos = observation['opponent_position']
    dx, dy = 0, 0
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    if resources:
        res = min(resources, key=lambda r: dist(px, py, r['position'][0], r['position'][1]))
        tx, ty = res['position']
    else:
        tx, ty = opponent_pos
    delta_x, delta_y = tx - px, ty - py
    move_x = (delta_x > 0) - (delta_x < 0)
    move_y = (delta_y > 0) - (delta_y < 0)
    if (px + move_x, py + move_y) in obstacles or not (0 <= px + move_x < width and 0 <= py + move_y < height):
        if (px + move_x, py) not in obstacles and 0 <= px + move_x < width:
            return [move_x, 0]
        if (px, py + move_y) not in obstacles and 0 <= py + move_y < height:
            return [0, move_y]
        else:
            for dx_opt, dy_opt in [[1,0], [-1,0], [0,1], [0,-1]]:
                nx, ny = px + dx_opt, py + dy_opt
                if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
                    return [dx_opt, dy_opt]
    return [move_x, move_y]
